        const onSeenHooks = def?.hooks?.onSeen;
        if (!hasQueuedAction && canActThisTurn && Array.isArray(onSeenHooks) && onSeenHooks.length > 0) {
          const seenCtx = new SeenCallbackContext(world, {
            actor:     id,
