        const losCtx = new SeenCallbackContext(world, {
          actor:     id,
          target:    playerId,
          actorPos:  { x: pos.x | 0, y: pos.y | 0 },
          targetPos: { x: playerPos.x | 0, y: playerPos.y | 0 },
