import { assert, assertEquals } from "jsr:@std/assert";
import { World } from '../src/lib/ecs-js/index.js';
import { Position } from '../src/rules/components/Position.js';
import { Player } from '../src/rules/components/Player.js';
import { NamedIdentity } from '../src/rules/components/NamedIdentity.js';
import { Faction } from '../src/rules/components/Faction.js';
import { Equipment } from '../src/rules/components/Equipment.js';
import { MoveIntent } from '../src/rules/components/Intents/MoveIntent.js';
import { Vitality } from '../src/rules/components/Vitality.js';
import { AggroState, AGGRO_LEVELS, SEARCH_TURNS_HUNTING_GRACE } from '../src/rules/components/AggroState.js';
import { ItemInfo } from '../src/rules/components/ItemInfo.js';
import { aiChaseSystem } from "./helpers/runChaseTactics.mjs";
import { areFactionsHostile } from '../src/rules/utils/factionHostility.js';
import { hasEquippedTag } from '../src/rules/utils/equipTags.js';

// ── Helpers ─────────────────────────────────────────────────────────────────

function addHuntingAggro(world, id, playerX, playerY) {
  world.add(id, AggroState, {
    alertLevel: AGGRO_LEVELS.hunting,
    lastKnownX: playerX,
    lastKnownY: playerY,
    searchTurnsLeft: SEARCH_TURNS_HUNTING_GRACE,
    retreating: false,
  });
}

function makePlayer(world, x, y) {
  const id = world.create();
  world.add(id, Player);
  world.add(id, Position, { x, y });
  world.add(id, NamedIdentity, { name: 'Hero', identity: 'player' });
  world.add(id, Equipment, {});
  return id;
}

function equipConflictRing(world, playerId) {
  const ringId = world.create();
  world.add(ringId, NamedIdentity, { name: 'Ring of Conflict', identity: 'ring_conflict' });
  world.add(ringId, ItemInfo, { type: 'equip', slot: 'ring', tags: ['conflict'] });
  const eq = world.get(playerId, Equipment);
  eq.ring1 = ringId;
  return ringId;
}

function makeEnemy(world, x, y, identity, playerX, playerY) {
  const id = world.create();
  world.add(id, Position, { x, y });
  world.add(id, NamedIdentity, { name: identity, identity });
  world.add(id, Faction, { key: 'enemy' });
  world.add(id, Vitality, { hp: 10, maxHp: 10 });
  addHuntingAggro(world, id, playerX, playerY);
  return id;
}

// ── hasEquippedTag utility ───────────────────────────────────────────────────

Deno.test("hasEquippedTag returns true when ring with tag is equipped", () => {
  const world = new World({ seed: 1 });
  const player = makePlayer(world, 5, 5);
  equipConflictRing(world, player);
  assert(hasEquippedTag(world, player, "conflict"), "should detect conflict tag");
});

Deno.test("hasEquippedTag returns false when no tagged item equipped", () => {
  const world = new World({ seed: 1 });
  const player = makePlayer(world, 5, 5);
  assert(!hasEquippedTag(world, player, "conflict"), "no ring = no conflict");
});

// ── Faction hostility ───────────────────────────────────────────────────────

Deno.test("enemy faction is not self-hostile without an explicit conflict source", () => {
  assert(!areFactionsHostile("enemy", "enemy"),
    "enemy-enemy should not create ambient infighting");
});

Deno.test("player faction is still not self-hostile", () => {
  assert(!areFactionsHostile("player", "player"),
    "player-player should not be hostile");
});

Deno.test("pet faction is still not self-hostile", () => {
  assert(!areFactionsHostile("pet", "pet"),
    "pet-pet should not be hostile");
});

// ── AI targeting with Ring of Conflict ──────────────────────────────────────

Deno.test("conflict ring: enemy chases nearest rival instead of player", () => {
  const world = new World({ seed: 42 });

  // Player at (5,5) with conflict ring
  const playerId = makePlayer(world, 5, 5);
  equipConflictRing(world, playerId);

  // Enemy A at (8,5) — hunting player at (5,5)
  const enemyA = makeEnemy(world, 8, 5, 'goblin', 5, 5);

  // Enemy B at (10,5) — another enemy, closer rival for A than the player
  const enemyB = makeEnemy(world, 10, 5, 'orc', 5, 5);

  aiChaseSystem(world);

  const intentA = world.get(enemyA, MoveIntent);
  assert(intentA, 'enemyA should have a MoveIntent');
  // Enemy A at (8,5), rival B at (10,5) → should chase east (+1, 0)
  assertEquals(intentA.dx, 1, 'enemyA should chase toward rival B (east)');
  assertEquals(intentA.dy, 0, 'enemyA should not move vertically');
});

Deno.test("conflict ring: enemy falls back to player when no rival in sight", () => {
  const world = new World({ seed: 43 });

  // Player at (5,5) with conflict ring
  const playerId = makePlayer(world, 5, 5);
  equipConflictRing(world, playerId);

  // Single enemy at (8,5) — no other enemies nearby
  const enemyA = makeEnemy(world, 8, 5, 'goblin', 5, 5);

  aiChaseSystem(world);

  const intent = world.get(enemyA, MoveIntent);
  assert(intent, 'enemy should have a MoveIntent');
  // No rival → falls back to chasing player at (5,5) → west (-1, 0)
  assertEquals(intent.dx, -1, 'lone enemy should chase player (west)');
  assertEquals(intent.dy, 0);
});

Deno.test("no conflict ring: enemies chase player normally", () => {
  const world = new World({ seed: 44 });

  // Player at (5,5) without conflict ring
  const playerId = makePlayer(world, 5, 5);

  // Two enemies
  const enemyA = makeEnemy(world, 8, 5, 'goblin', 5, 5);
  const enemyB = makeEnemy(world, 10, 5, 'orc', 5, 5);

  aiChaseSystem(world);

  const intentA = world.get(enemyA, MoveIntent);
  assert(intentA, 'enemyA should have MoveIntent');
  // Should chase player at (5,5) → west (-1, 0)
  assertEquals(intentA.dx, -1, 'enemyA should chase player (west) without conflict ring');
  assertEquals(intentA.dy, 0);
});

Deno.test("conflict ring: enemy targets closest rival, not farthest", () => {
  const world = new World({ seed: 45 });

  const playerId = makePlayer(world, 0, 5);
  equipConflictRing(world, playerId);

  // Enemy A at (5,5)
  const enemyA = makeEnemy(world, 5, 5, 'goblin', 0, 5);

  // Enemy B at (9,5) — far rival (dist 4)
  const enemyB = makeEnemy(world, 9, 5, 'orc', 0, 5);

  // Enemy C at (3,5) — close rival (dist 2)
  const enemyC = makeEnemy(world, 3, 5, 'rat', 0, 5);

  aiChaseSystem(world);

  const intentA = world.get(enemyA, MoveIntent);
  assert(intentA, 'enemyA should have MoveIntent');
  // Closest rival is C at (3,5) → west (-1, 0)
  assertEquals(intentA.dx, -1, 'enemyA should chase nearest rival C (west)');
  assertEquals(intentA.dy, 0);
});

Deno.test("conflict ring unequipped: enemies revert to chasing player", () => {
  const world = new World({ seed: 46 });

  // Player at (5,5) — ring equipped then removed
  const playerId = makePlayer(world, 5, 5);
  const ringId = equipConflictRing(world, playerId);

  const enemyA = makeEnemy(world, 8, 5, 'goblin', 5, 5);
  const enemyB = makeEnemy(world, 10, 5, 'orc', 5, 5);

  // Remove the ring
  const eq = world.get(playerId, Equipment);
  eq.ring1 = 0;

  aiChaseSystem(world);

  const intent = world.get(enemyA, MoveIntent);
  assert(intent, 'enemyA should have MoveIntent');
  assertEquals(intent.dx, -1, 'enemyA should revert to chasing player (west)');
  assertEquals(intent.dy, 0);
});
import { Faction } from "../components/Faction.js";
import { Player } from "../components/Player.js";
import { Position } from "../components/Position.js";

export function classifyAggroTarget(world, targetId) {
  const id = Number(targetId || 0) | 0;
  if (!(id > 0)) return "none";
  if (world.has(id, Player)) return "player";
  const factionKey = String(world.get(id, Faction)?.key || "").trim().toLowerCase();
  if (factionKey === "pet" || factionKey === "summoned" || factionKey === "stone_taunter") return "ally";
  return "npc";
}

export function setAggroTarget(world, sourceId, aggro, targetId, reason = "selected") {
  const nextTargetId = Number(targetId || 0) | 0;
  const prevTargetId = Number(aggro?.targetId || 0) | 0;
  const nextReason = String(reason || "selected");
  const prevReason = String(aggro?.targetReason || "");
  if (!aggro) return;
  if (prevTargetId === nextTargetId && prevReason === nextReason) return;

  aggro.targetId = nextTargetId;
  aggro.targetReason = nextTargetId > 0 ? nextReason : "";
  if (!(nextTargetId > 0)) return;

  const sourcePos = world.get(sourceId, Position);
  const targetPos = world.get(nextTargetId, Position);
  world.emit?.("aggro:targetChanged", {
    sourceId,
    targetId: nextTargetId,
    previousTargetId: prevTargetId,
    reason: nextReason,
    sourceFaction: String(world.get(sourceId, Faction)?.key || ""),
    targetFaction: String(world.get(nextTargetId, Faction)?.key || ""),
    targetKind: classifyAggroTarget(world, nextTargetId),
    sourcePos: sourcePos ? { x: sourcePos.x | 0, y: sourcePos.y | 0 } : null,
    targetPos: targetPos ? { x: targetPos.x | 0, y: targetPos.y | 0 } : null,
  });
}
import { attach, detach } from "../../lib/ecs-js/hierarchy.js";
import { ThreatEntry } from "../components/ThreatEntry.js";
import { AggroState } from "../components/AggroState.js";
import { Equipment, NON_AMMO_GEAR_SLOTS } from "../components/Equipment.js";
import { ItemInfo } from "../components/ItemInfo.js";
import { Position } from "../components/Position.js";
import { childrenWith } from "./topology.js";
import { setAggroTarget } from "./aggroTarget.js";
import { chebyshevScalar } from "./distance.js";

export const THREAT_SWITCH_MELEE_MULT = 1.10;
export const THREAT_SWITCH_RANGED_MULT = 1.30;
export const THREAT_TAUNT_MARGIN = 5;
export const THREAT_SOFT_TAUNT_BURST = 6;
export const THREAT_MIN_GENERATION_MULT = 0.25;
export const THREAT_MAX_GENERATION_MULT = 2.5;

function readTurn(world) {
  return Math.max(0, Number(world?.step || 0) | 0);
}

function normalizeId(value) {
  const id = Number(value || 0) | 0;
  return id > 0 ? id : 0;
}

function destroyThreatEntry(world, entryId) {
  const id = normalizeId(entryId);
  if (!id || !world?.isAlive?.(id)) return false;
  try { detach(world, id, { remove: true }); } catch {}
  world.destroy(id);
  return true;
}

export function getThreatEntries(world, ownerId) {
  const out = [];
  const owner = normalizeId(ownerId);
  if (!owner || !world?.isAlive?.(owner)) return out;
  for (const [entryId, entry] of childrenWith(world, owner, ThreatEntry)) {
    out.push([entryId, entry]);
  }
  return out;
}

export function findThreatEntry(world, ownerId, sourceId) {
  const source = normalizeId(sourceId);
  if (!source) return null;
  for (const [entryId, entry] of getThreatEntries(world, ownerId)) {
    if ((Number(entry.sourceId || 0) | 0) === source) return [entryId, entry];
  }
  return null;
}

export function getThreatValue(world, ownerId, sourceId) {
  const found = findThreatEntry(world, ownerId, sourceId);
  return found ? Math.max(0, Number(found[1].value || 0) | 0) : 0;
}

export function getHighestThreat(world, ownerId) {
  let bestId = 0;
  let bestValue = 0;
  let bestEntryId = 0;
  for (const [entryId, entry] of getThreatEntries(world, ownerId)) {
    const sourceId = normalizeId(entry.sourceId);
    const value = Math.max(0, Number(entry.value || 0) | 0);
    if (!sourceId || !world.isAlive(sourceId) || value <= 0) continue;
    if (value > bestValue || (value === bestValue && sourceId < bestId)) {
      bestId = sourceId;
      bestValue = value;
      bestEntryId = entryId;
    }
  }
  return { sourceId: bestId, value: bestValue, entryId: bestEntryId };
}

export function addThreat(world, ownerId, sourceId, amount, opts = {}) {
  const owner = normalizeId(ownerId);
  const source = normalizeId(sourceId);
  const delta = Math.max(0, Number(amount || 0) | 0);
  if (!owner || !source || owner === source || delta <= 0) return null;
  if (!world?.isAlive?.(owner) || !world.isAlive(source)) return null;
  if (!world.get(owner, AggroState)) return null;

  let found = findThreatEntry(world, owner, source);
  if (!found) {
    const entryId = world.create();
    world.add(entryId, ThreatEntry, {
      sourceId: source,
      value: 0,
      lastTurnTouched: readTurn(world),
      kind: String(opts.kind || ""),
      forcedUntilTurn: 0,
      decayRate: Math.max(1, Number(opts.decayRate || 2) | 0),
      sticky: !!opts.sticky,
    });
    attach(world, entryId, owner);
    found = [entryId, world.get(entryId, ThreatEntry)];
  }

  const entry = found[1];
  entry.value = Math.max(0, (Number(entry.value || 0) | 0) + delta);
  entry.lastTurnTouched = readTurn(world);
  entry.kind = String(opts.kind || entry.kind || "");
  entry.decayRate = Math.max(1, Number(opts.decayRate || entry.decayRate || 2) | 0);
  entry.sticky = !!(opts.sticky || entry.sticky);
  return found;
}

export function reduceThreat(world, ownerId, sourceId, amount, opts = {}) {
  const found = findThreatEntry(world, ownerId, sourceId);
  if (!found) return 0;
  const entry = found[1];
  const before = Math.max(0, Number(entry.value || 0) | 0);
  const flat = Math.max(0, Number(amount || 0) | 0);
  const pct = Math.max(0, Math.min(1, Number(opts.percent || opts.pct || 0)));
  const next = Math.max(0, Math.floor((before - flat) * (1 - pct)));
  entry.value = next;
  entry.lastTurnTouched = readTurn(world);
  if (next <= 0) {
    destroyThreatEntry(world, found[0]);
  }
  return before - next;
}

export function clearThreatFromSource(world, sourceId, opts = {}) {
  const source = normalizeId(sourceId);
  if (!source) return 0;
  let changed = 0;
  for (const [ownerId, aggro] of world.query(AggroState)) {
    const found = findThreatEntry(world, ownerId, source);
    if (!found) continue;
    const before = Math.max(0, Number(found[1].value || 0) | 0);
    if (opts.destroy === false) found[1].value = 0;
    destroyThreatEntry(world, found[0]);
    changed += before;
    if ((Number(aggro.targetId || 0) | 0) === source) {
      setAggroTarget(world, ownerId, aggro, 0, String(opts.reason || "threat_drop"));
    }
    if ((Number(aggro.highestThreatId || 0) | 0) === source) aggro.highestThreatId = 0;
    if ((Number(aggro.forcedTargetId || 0) | 0) === source) {
      aggro.forcedTargetId = 0;
      aggro.forcedUntilTurn = 0;
    }
  }
  return changed;
}

export function reduceThreatFromSource(world, sourceId, opts = {}) {
  const source = normalizeId(sourceId);
  if (!source) return 0;
  let changed = 0;
  for (const [ownerId] of world.query(AggroState)) {
    changed += reduceThreat(world, ownerId, source, opts.amount || 0, opts);
    resolveThreatTarget(world, ownerId, { reason: String(opts.reason || "threat_drop") });
  }
  return changed;
}

export function getThreatGenerationMultiplier(world, sourceId) {
  const source = normalizeId(sourceId);
  if (!source || !world?.isAlive?.(source)) return 1;
  let mult = 1;
  const eq = world.get(source, Equipment);
  if (!eq) return mult;

  for (const slot of NON_AMMO_GEAR_SLOTS) {
    const itemId = normalizeId(eq[slot]);
    if (!itemId || !world.isAlive(itemId)) continue;
    const info = world.get(itemId, ItemInfo);
    if (!info) continue;
    const bonuses = info.bonuses && typeof info.bonuses === "object" ? info.bonuses : {};
    if (Number.isFinite(Number(bonuses.threatGenerationMult))) {
      mult *= Number(bonuses.threatGenerationMult);
    }
    if (Number.isFinite(Number(bonuses.threatMult))) {
      mult *= Number(bonuses.threatMult);
    }
    if (Number.isFinite(Number(bonuses.threatReduction))) {
      mult *= Math.max(0, 1 - Number(bonuses.threatReduction));
    }

