const MONSTER_BASELINE = Object.freeze([
  Position,
  NamedIdentity,
  Faction,
  Collider,
  Inventory,
  Equipment,
  Vitality,
  Speed,
  Resistances,
  Anatomy,
  Physiology,
  Wounds,
  ActiveEffects,
