    source,
    attribution,
    protectedTarget,
    offenseKind,
    offenseLabel: def.label,
    severity,
    severityName: severityName(severity),
    requiresConfirm,
    message: requiresConfirm
      ? `${def.label}: ${actionKind === "melee_attack" ? "attack" : "target"} ${targetName}?`
      : "",
  });
}

